for (int i = 1; i < str.length(); i++) {
char x = str.charAt(i);
if (x == first) counter[i] += 0; else ++counter[i];
}
for (int i = 1; i < counter.length; i++) {
first = str.charAt(i - 1);
char z = str.charAt(i);
if (z == first) ++counter[i];
}
return (counter[counter.length - 1]);
}

