public static Object rearrangeBigger(int n) {
String s = String.valueOf(n);
char[] c = s.toCharArray();
int i = 0;
while (i < c.length - 1) {
if (c[i] < c[i + 1]) {
break;
}
i = i + 1;
}
if (i == c.length - 1) {
return false;
}
int j = c.length - 1;
while (j > i) {
if (c[j] > c[i]) {
break;
}
--j;
}
char tmp = c[i];
c[i] = c[j];
c[j] = tmp;
StringBuilder sb = new StringBuilder();
for (char c1 : c) {
sb.append(c1);
}
return Integer.valueOf(sb.toString());
}

