public static List<Integer> maxProduct(List<Integer> arr) {
List<Integer> maxProduct = new ArrayList<>();
int maxProductValue = Integer.MIN_VALUE;
for (int i = 0; i < arr.size(); i++) {
for (int j = i + 1; j < arr.size(); j++) {
int product = arr.get(i) * arr.get(j);
if (product > maxProductValue) {
maxProductValue = product;
maxProduct = new ArrayList<>();
maxProduct.add(arr.get(i));
maxProduct.add(arr.get(j));
} else if (product == maxProductValue) {
maxProduct.add(arr.get(i));
maxProduct.add(arr.get(j));
}
}
}
return maxProduct;
}

public static int breaksum(int n) {
if (n == 0) return 0;
int temp = n;
for (int i = 2; i <= n; i++) {
temp = Math.max(temp, breaksum(i / 2) + breaksum(i / 3) + breaksum(i / 4));
}
return temp;
}

public static List<List<String>> groupTuples(List<List<String>> input) {
Set<String> set = new HashSet<>();
List<List<String>> result = new ArrayList<>();
for (List<String> strings : input) {
if (set.contains(strings.get(0))) {
result.get(result.size() - 1).add(strings.get(1));
} else {
set.add(strings.get(0));
result.add(new ArrayList<>(Arrays.asList(strings.get(0), strings.get(1))));
}
}
