int mid = left + (right - left) / 2;
if (arr.get(left) > arr.get(mid) && arr.get(mid) > arr.get(right)) {
right = mid;
} else if (arr.get(left) < arr.get(mid) && arr.get(mid) < arr.get(right)) {
left = mid + 1;
