for (int i = 1; i <= row; i++) {
for (int j = 1; j <= col; j++) {
dp[i][j] = cost.get(i - 1).get(j - 1) + Math.max(dp[i - 1][j], dp[i][j - 1]);
}
}
return dp[row][col] / (2 * row - 1);
}

