public static int nthSuperUglyNumber(int n, List<Integer> primes) {
PriorityQueue<Integer> pq = new PriorityQueue<>();
int count = 1;
pq.offer(1);
while (count < n) {
int min = pq.poll();
for (int prime : primes) {
int next = min * prime;
if (pq.contains(next)) {
continue;
}
pq.offer(next);
}
count = count + 1;
}
return pq.poll();
}

