char c2 = str2.charAt(0);
int i1 = 1, i2 = 1;
while (i1 < len1 && i2 < len2) {
if (c1 != c2) {
i1 = i1 + 1;
++i2;
} else if (i1 >= len1) {
i1 = 0;
return false;
} else if (i2 >= len2) {
i2 = 0;
