public static int minSumPath(List<List<Integer>> a) {
int[] dp = new int[a.size()];
dp[0] = a.get(0).get(0);
for (int i = 1; i < a.size(); i++) {
dp[i] = Math.min(dp[i - 1] + a.get(i).get(0), dp[i - 1] + a.get(i).get(1));
}
return dp[dp.length - 1];
}
